import{d as p,C as s,o as g,c as d,a3 as t,E as i,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第四十二章","description":"《正易心法》第四十二章——世俗学解，浸渍旧闻：以《春秋》与《左传》为比，说学者玩其文辞而本经微旨泯；不知借辞以明画象，遂溺其辞，加以古今训注而袭谬承误，使羲皇初意不行于世——「呜乎！」","frontmatter":{"title":"正易心法·第四十二章","description":"《正易心法》第四十二章——世俗学解，浸渍旧闻：以《春秋》与《左传》为比，说学者玩其文辞而本经微旨泯；不知借辞以明画象，遂溺其辞，加以古今训注而袭谬承误，使羲皇初意不行于世——「呜乎！」","category":"guide","aliases":["正易心法第四十二章","世俗学解浸渍旧闻","呜乎"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-42.md","filePath":"yijing/zheng-yi-xin-fa/chapter-42.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-42.md"},x=p({...c,setup(u){const e=[{id:"z42-01",label:"一、世俗学解",showLabel:!0,sentences:[["世俗学解，",{text:"浸渍旧闻",glossary:"jinziJiuwen"},"。失其",{text:"本始",glossary:"benshi"},"，易道",{text:"浅狭",glossary:"qianxia"},"。"]],note:["世俗的学问解读，浸泡在旧有的见闻里；失去了根本与起始，易道因此变得浅薄狭窄。（**「本始」＝羲皇画卦的初意。** 这是全书正文的最后一章，也是**批评的收口**：从第一章「不知落处」到此处的「失其本始」，**麻衣批的是同一件事——把活的做成死的。**）"]},{id:"z42-02",label:"二、春秋与左氏之比",showLabel:!0,sentences:[["羲皇氏正《易》，《春秋》比也。周、孔明《易》，作传比也。左氏本为《春秋》作传，而世乃玩其文辞，致左氏",{text:"孤行",glossary:"guxing"},"，而《春秋》之",{text:"微旨",glossary:"weizhi"},"泯矣。"]],note:["伏羲创制《易》，就像《春秋》的地位；周文王、周公、孔子阐明《易》，就像为《春秋》作传。《左传》本来是为《春秋》作传的，但世人只是玩味《左传》的文辞，导致《左传》单独流行，而《春秋》深微的宗旨就消失了。（**这个类比极有说服力**：《春秋》本经字数少、一字褒贬；《左传》文采斐然、故事生动——**结果人人读《左传》，《春秋》被冷落。** 麻衣用它说：**《易》的处境一模一样，卦画（本经）被卦辞（传）淹没了。**）"]},{id:"z42-03",label:"三、易之有辞",showLabel:!0,sentences:[["《易》之有辞，本为羲皇发扬。学者不知",{text:"借辞以明其画象",glossary:"jieciMingxiang"},"，遂",{text:"溺其辞",glossary:"niqici"},"，"]],note:["《易》有文辞，本来是为了发扬伏羲的卦象；学者不知道应该借助文辞来阐明卦画之象，反而沉溺于文辞。（**正确顺序**：画象（主）→ 文辞（从）→ 借辞以明画象。**错误顺序**：文辞（主）→ 溺其辞 → 离画象越来越远。**辞是过河的桥，过了桥要到彼岸，不是要在桥上盖房子。**）"]},{id:"z42-04",label:"四、袭谬承误",showLabel:!0,sentences:[["加以古今训注而",{text:"袭谬承误",glossary:"ximiuChengwu"},"，使",{text:"羲皇初意",glossary:"xihuangChuyi"},"不行于世，而《易》道于此浅狭矣。"]],note:["加上历代的训诂注释，一代代沿袭错误、继承谬误，使得伏羲最初的意图不能流行于世，《易》道就在这里变得浅薄狭窄了。（**这是一个「雪球效应」**：第一代（羲皇画卦、周孔作辞）失真一次；此后**汉儒注经、魏晋注汉儒、唐人注魏晋、宋人注唐人**——每层注解都在解释上一层，同时也遮蔽上一层。**麻衣不是批评某一个注家，他批评的是这个机制本身**：每一代人都在认真传递，但传递的过程本身就是失真的过程。）"]},{id:"z42-05",label:"五、呜乎",showLabel:!0,sentences:[[{text:"呜乎",glossary:"wuhu"},"！"]],note:["唉——！（**这是全书唯一的感叹词。** 前四十一章麻衣的语气一贯是：「此之谓也」（肯定）、「失之甚矣」（批评）、「是为定论」（确认）、「颇得之」（评价）——**冷静，克制，精准。** 而这一章的最后，他写了「呜乎」：**不是愤怒，不是绝望，是一种深沉的、无可奈何的悲悯。** 他看见了羲皇初意，也知道那个初意在他的时代已经「不行于世」；**而他写的这四十二章，也是文字，也可能成为下一代人「袭谬承误」的材料。** 这是**一个清醒者的叹息**。）"]}],o=[{id:"jinziJiuwen",term:"浸渍旧闻",pinyin:"jìn zì jiù wén",meaning:"浸泡在旧有的见闻里。浸渍＝浸泡渗透；旧闻＝前人的说法。"},{id:"benshi",term:"本始",pinyin:"běn shǐ",meaning:"根本与起始。本始＝羲皇画卦的初意。"},{id:"qianxia",term:"浅狭",pinyin:"qiǎn xiá",meaning:"浅薄狭窄。《易》道本来宽广，被学者弄得浅薄了。"},{id:"guxing",term:"孤行",pinyin:"gū xíng",meaning:"单独流行。脱离了本经而独立流传。"},{id:"weizhi",term:"微旨",pinyin:"wēi zhǐ",meaning:"深微的宗旨。《春秋》的真意被《左传》的文辞遮蔽。"},{id:"jieciMingxiang",term:"借辞以明其画象",pinyin:"jiè cí yǐ míng",meaning:"借助文辞来阐明卦画之象。辞是手段，象是目的。"},{id:"niqici",term:"溺其辞",pinyin:"nì qí cí",meaning:"沉溺于文辞。把手段当成了目的。"},{id:"ximiuChengwu",term:"袭谬承误",pinyin:"xí miù chéng wù",meaning:"沿袭错误、继承谬误。一代代把错误当正确传下去。"},{id:"xihuangChuyi",term:"羲皇初意",pinyin:"xī huáng chū yì",meaning:"伏羲最初的意图。画卦时那个直接感知天地的心地。"},{id:"wuhu",term:"呜乎",pinyin:"wū hū",meaning:"叹词。全书唯一的感叹，沉痛之极。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第四十二章" tabindex="-1">正易心法·第四十二章 <a class="header-anchor" href="#正易心法·第四十二章" aria-label="Permalink to &quot;正易心法·第四十二章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是<strong>全书正文的最后一章</strong>，也是批评的收口：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>核心命题：世俗学解浸渍旧闻，失其本始，易道浅狭</span></span>
<span class="line"><span></span></span>
<span class="line"><span>论证：</span></span>
<span class="line"><span>  《春秋》与《左传》的平行类比</span></span>
<span class="line"><span>    《春秋》（本经）→ 左氏作传 → 世人玩其文辞 → 左氏孤行 → 微旨泯矣</span></span>
<span class="line"><span>    《易》（卦画）→ 周孔作辞 → 学者溺其辞 → 辞孤行 → 羲皇初意不行于世</span></span></code></pre></div><p><strong>结论</strong>：<strong>「呜乎！」</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>《春秋》与《易》的平行结构</strong>：</p><table tabindex="0"><thead><tr><th>《春秋》系统</th><th>《易》系统</th></tr></thead><tbody><tr><td>《春秋》本经（孔子）</td><td>卦画（羲皇）</td></tr><tr><td>《左传》（左丘明作传）</td><td>卦辞爻辞十翼（周孔作传）</td></tr><tr><td>世人玩《左传》文辞</td><td>学者溺其辞、束于辞训</td></tr><tr><td>左氏孤行</td><td>辞孤行</td></tr><tr><td><strong>《春秋》微旨泯矣</strong></td><td><strong>羲皇初意不行于世</strong></td></tr></tbody></table><p><strong>麻衣的判断</strong>：<strong>两个系统犯了同一个错误——把「传」当成了「经」，把「手段」当成了「目的」，把「窗户」当成了「风景」。</strong></p><p><strong>「借辞以明画象」的主从关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正确顺序：</span></span>
<span class="line"><span>  画象（卦画）＝ 主，是目的</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>  文辞（卦辞爻辞）＝ 从，是工具</span></span>
<span class="line"><span>       ↓ 借辞</span></span>
<span class="line"><span>  明画象（理解卦画的意思）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误的顺序（世俗学解）：</span></span>
<span class="line"><span>  文辞 ＝ 主 → 加上古今训注 ＝ 更多的文辞 → 离画象越来越远</span></span></code></pre></div><p><strong>「袭谬承误」的雪球效应</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一代：羲皇画卦（无文字，直接感知）→ 周文王作卦辞（文字化，有所失真）→ 孔子作十翼（再次文字化）</span></span>
<span class="line"><span>第二代以后：汉儒注《易》→ 魏晋注汉儒 → 唐人注魏晋 → 宋人注唐人 → ……</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每一层注解都在「解释」上一层，同时也在「遮蔽」上一层</span></span>
<span class="line"><span>= 就像传话游戏：每个人都认真地转述，但传到最后，第一句话已经面目全非</span></span></code></pre></div><p><strong>「呜乎」——全书唯一的叹息</strong>：</p><blockquote><p>前四十一章麻衣几乎从不用感叹词。而这一章的最后，他写了「呜乎」。这两个字，是全书最重的两个字。</p></blockquote><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把《春秋》／《左传》的类比读懂——<strong>这是本章最有说服力的部分</strong>；</li><li>再看「借辞以明其画象」——<strong>这是全书的读法总纲</strong>；</li><li>最后停在「呜乎」两个字上——<strong>不要急着分析，就坐在这个叹息里。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>浸渍旧闻</strong>：浸泡在前人的说法里。</li><li><strong>失其本始</strong>：失去羲皇画卦的初意。</li><li><strong>春秋之比</strong>：本经被传淹没。</li><li><strong>借辞以明画象</strong>：辞是手段，象是目的。</li><li><strong>袭谬承误</strong>：注解的雪球效应。</li><li><strong>呜乎</strong>：全书唯一的叹息。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,20)),i(r,{colophon:"世俗学解 · 春秋之比 · 借辞明象 · 呜乎",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四十二章原文",sections:e,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(l,{items:[{term:"浸渍旧闻",pinyin:["jìn","zì"],meaning:"浸泡在旧有的见闻里——只知传述，不知本始。"},{term:"春秋之比",pinyin:["chūn","qiū"],meaning:"《春秋》本经被《左传》的文辞淹没，《易》的卦画也被卦辞淹没——两个系统犯了同一个错误。"},{term:"借辞以明其画象",pinyin:["jiè","cí"],meaning:"借助文辞来阐明卦画之象。辞是过河的桥，过了桥要到彼岸，不是在桥上盖房子。"},{term:"袭谬承误",pinyin:["xí","miù"],meaning:"一代代沿袭错误。每一代人都在认真传递，但传递的过程本身就是失真的过程——雪球效应。"},{term:"呜乎",pinyin:["wū","hū"],meaning:"全书唯一的感叹词。不是愤怒或绝望，而是一个清醒者的悲悯与叹息。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>全书正文的最后一章</strong>，用《春秋》与《左传》的类比，说明「传」如何淹没了「经」，导致「羲皇初意不行于世」。</p><p><strong>结论：呜乎！</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「借辞以明画象」的主从关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正确：画象（主／目的）→ 文辞（从／工具）→ 借辞 → 明画象</span></span>
<span class="line"><span>错误：文辞（主）→ 古今训注（更多文辞）→ 离画象越来越远</span></span></code></pre></div><p><strong>「袭谬承误」的雪球效应</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每一层注解都在「解释」上一层，同时也在「遮蔽」上一层</span></span>
<span class="line"><span>= 就像传话游戏：每个人都认真地转述，但第一句话已经面目全非</span></span></code></pre></div><p><strong>「呜乎」的分量</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前四十一章的语气：此之谓也（肯定）、失之甚矣（批评）、是为定论（确认）、颇得之（评价）</span></span>
<span class="line"><span>——冷静，克制，精准</span></span>
<span class="line"><span></span></span>
<span class="line"><span>本章末：呜乎</span></span>
<span class="line"><span>——这是全书唯一的感叹词，也是最重的两个字</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>读懂《春秋》／《左传》的类比——<strong>它比任何道理都直观</strong>；</li><li>记住「借辞以明画象」：<strong>辞是桥，不是家</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>我们读这四十二章，离羲皇初意是更近了，还是更远了？</strong> 我的看法：<strong>这个问题的答案不在「读了多少」，而在「读完之后的那个瞬间」。</strong> 麻衣自己在全书末尾就承认：<strong>他写的也是文字，也可能成为下一代人「袭谬承误」的材料。</strong> 但他仍然写了——<strong>因为不写更不行。</strong> 所以**「更近」还是「更远」，取决于你读完这本书之后，看那一横两横的眼睛有没有变。** 如果变了，<strong>这本书就在你身上做完了它的事</strong>；如果不是，<strong>它就只是你和羲皇之间的又一层纸。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>世俗的学问解读，浸泡在旧有的见闻里；失去了根本与起始，易道因此变得浅薄狭窄。</p><p>伏羲创制《易》，就像《春秋》的地位；周文王、周公、孔子阐明《易》，就像为《春秋》作传。《左传》本来是为《春秋》作传的，但世人只是玩味《左传》的文辞，导致《左传》单独流行，而《春秋》深微的宗旨就消失了。</p><p>《易》有文辞，本来是为了发扬伏羲的卦象；学者不知道应该借助文辞来阐明卦画之象，反而沉溺于文辞，加上历代的训诂注释，一代代沿袭错误、继承谬误，使得伏羲最初的意图不能流行于世，《易》道就在这里变得浅薄狭窄了。</p><p>唉——！</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第四十二章用《春秋》被《左传》淹没这件事，说清了《易》的处境——<strong>然后，麻衣只留下两个字：「呜乎」。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>《春秋》的类比</strong>——<strong>这是全书最有说服力的一段论证</strong>。<strong>《春秋》字数少，《左传》好看</strong>——结果人人读《左传》，本经被冷落。<strong>麻衣借宋人共同的痛，说他们没意识到的病。</strong></li><li><strong>「借辞以明其画象」</strong>——<strong>这八个字是全书的读法总纲</strong>：<strong>辞是桥，不是家。</strong> 从第一章「不知落处」，到第二十四章「《易》在日用」，到此处的「借辞明象」，<strong>麻衣说的是同一件事。</strong></li><li><strong>「袭谬承误」</strong>——<strong>雪球效应</strong>。要注意麻衣的分寸：<strong>他不是在骂某个注家，他说的是机制。</strong> 每一代人都在认真传递，<strong>但传递本身就是失真的过程。</strong></li><li><strong>「呜乎」</strong>——<strong>全书唯一的感叹词。</strong> 我读到这里时停了很久。<strong>前四十一章那么冷静的人，最后只留了两个字。</strong> 这不是愤怒，也不是绝望——<strong>是他知道，他写的这四十二章，本身也会成为下一代人的「纸」。</strong></li><li><strong>「呜乎」也是邀请</strong>——<strong>他叹的那口气，是在说：门在这里，我已经指了四十二章，进不进去，是你自己的事。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>我们读这四十二章，离羲皇初意是更近了，还是更远了？</strong> 我的看法：<strong>答案不在「读了多少」，而在「读完之后的那个瞬间」。</strong> 麻衣自己就承认：<strong>他写的也是文字，也可能成为下一代人「袭谬承误」的材料。</strong> 但他还是写了——<strong>因为不写更不行。</strong> 所以「更近」还是「更远」，<strong>取决于你读完这本书之后，看那一横两横的眼睛有没有变。</strong> 如果变了，<strong>这本书就在你身上做完了它的事</strong>；如果不是，<strong>它就只是你和羲皇之间的又一层纸。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「不知落处」（本章「失其本始」是其反面）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-03">第三章 · 卦象视人</a> — 「本无文字」（本章「借辞以明画象」是其展开）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 「买椟还珠」（本章的「溺其辞」）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-41">第四十一章 · 九流可入</a> — 「活法」与「羲皇心地」</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/postscript">后序与跋</a> — 全书正文之后的两篇文字</li></ul>`,24))])}}});export{y as __pageData,x as default};
